{"total_lines": 144, "text": "1: // WebAssembly platform layer for doomgeneric (Emscripten, Asyncify).
2: //
3: // - Rendering: DG_DrawFrame converts the engine's B,G,R,0 pixels to opaque
4: //   RGBA and blits to <canvas id="canvas"> via putImageData.
5: // - Timing: DG_GetTicksMs uses emscripten_get_now(); DG_SleepMs yields to the
6: //   browser with emscripten_sleep (Asyncify) so wipe/tic waits don't freeze it.
7: // - Input: JS calls dg_key(pressed, doomKey); DG_GetKey drains a ring buffer.
8: // - Entry: main() creates the game then ticks forever, yielding every frame.
9: 
10: #include <stdint.h>
11: #include <stdlib.h>
12: #include <stdio.h>
13: #include <string.h>
14: #include <emscripten.h>
15: 
16: #include "doomgeneric.h"
17: #include "doomstat.h"
18: 
19: #define KEYQ_SIZE 256
20: static struct { unsigned char pressed, key; } keyq[KEYQ_SIZE];
21: static unsigned keyq_r, keyq_w;
22: 
23: static uint32_t rgba[DOOMGENERIC_RESX * DOOMGENERIC_RESY];
24: static uint32_t frame_count, tick_count;
25: 
26: EM_JS(void, js_present, (const uint32_t *px, int w, int h), {
27:     var c = Module.canvas || document.getElementById('canvas');
28:     if (!c) return;
29:     if (!Module.__ctx) {
30:         Module.__ctx = c.getContext('2d');
31:         Module.__img = null;
32:     }
33:     if (!Module.__img || Module.__img.width != w || Module.__img.height != h)
34:         Module.__img = Module.__ctx.createImageData(w, h);
35:     Module.__img.data.set(HEAPU8.subarray(px, px + w * h * 4));
36:     Module.__ctx.putImageData(Module.__img, 0, 0);
37: });
38: 
39: EM_JS(void, js_title, (const char *t), {
40:     document.title = UTF8ToString(t);
41: });
42: 
43: void DG_Init() {}
44: 
45: void DG_DrawFrame()
46: {
47:     const uint32_t *src = (const uint32_t *)DG_ScreenBuffer;
48:     for (int i = 0; i < DOOMGENERIC_RESX * DOOMGENERIC_RESY; i++) {
49:         uint32_t p = src[i];                       // 0x00RRGGBB
50:         rgba[i] = 0xFF000000u | ((p & 0xFF) << 16) | (p & 0xFF00) |
51:                   ((p >> 16) & 0xFF);              // bytes R,G,B,255
52:     }
53:     js_present(rgba, DOOMGENERIC_RESX, DOOMGENERIC_RESY);
54:     frame_count++;
55: }
56: 
57: void DG_SleepMs(uint32_t ms)
58: {
59:     emscripten_sleep(ms);
60: }
61: 
62: uint32_t DG_GetTicksMs()
63: {
64:     return (uint32_t)emscripten_get_now();
65: }
66: 
67: int DG_GetKey(int *pressed, unsigned char *key)
68: {
69:     if (keyq_r == keyq_w) return 0;
70:     *pressed = keyq[keyq_r % KEYQ_SIZE].pressed;
71:     *key = keyq[keyq_r % KEYQ_SIZE].key;
72:     keyq_r++;
73:     return 1;
74: }
75: 
76: void DG_SetWindowTitle(const char *title)
77: {
78:     js_title(title);
79: }
80: 
81: EMSCRIPTEN_KEEPALIVE void dg_key(int pressed, int key)
82: {
83:     if (keyq_w - keyq_r >= KEYQ_SIZE || key <= 0 || key > 255) return;
84:     keyq[keyq_w % KEYQ_SIZE].pressed = pressed ? 1 : 0;
85:     keyq[keyq_w % KEYQ_SIZE].key = (unsigned char)key;
86:     keyq_w++;
87: }
88: 
89: EMSCRIPTEN_KEEPALIVE uint32_t dg_frame_count(void) { return frame_count; }
90: EMSCRIPTEN_KEEPALIVE uint32_t dg_tick_count(void) { return tick_count; }
91: 
92: // Read-only observations for browser verification. gametic counts simulation
93: // tics; tick_count above counts outer loop calls and is not a timing metric.
94: EMSCRIPTEN_KEEPALIVE int dg_game_tics(void) { return gametic; }
95: EMSCRIPTEN_KEEPALIVE int dg_menu_active(void) { return menuactive; }
96: EMSCRIPTEN_KEEPALIVE int dg_in_level(void) {
97:     return gamestate == GS_LEVEL && !demoplayback && players[consoleplayer].mo != NULL;
98: }
99: EMSCRIPTEN_KEEPALIVE int dg_player_x(void) {
100:     return players[consoleplayer].mo ? players[consoleplayer].mo->x : 0;
101: }
102: EMSCRIPTEN_KEEPALIVE int dg_player_y(void) {
103:     return players[consoleplayer].mo ? players[consoleplayer].mo->y : 0;
104: }
105: EMSCRIPTEN_KEEPALIVE uint32_t dg_player_angle(void) {
106:     return players[consoleplayer].mo ? players[consoleplayer].mo->angle : 0;
107: }
108: EMSCRIPTEN_KEEPALIVE int dg_bullets(void) { return players[consoleplayer].ammo[am_clip]; }
109: EMSCRIPTEN_KEEPALIVE int dg_use_down(void) { return players[consoleplayer].usedown; }
110: EMSCRIPTEN_KEEPALIVE int dg_paused(void) { return paused; }
111: EMSCRIPTEN_KEEPALIVE int dg_automap(void) { return automapactive; }
112: EMSCRIPTEN_KEEPALIVE int dg_weapon(void) { return players[consoleplayer].readyweapon; }
113: EMSCRIPTEN_KEEPALIVE int dg_forward(void) { return players[consoleplayer].cmd.forwardmove; }
114: EMSCRIPTEN_KEEPALIVE int dg_side(void) { return players[consoleplayer].cmd.sidemove; }
115: 
116: EM_JS(void, js_fatal, (const char *t), {
117:     var m = UTF8ToString(t);
118:     var s = document.getElementById('status');
119:     if (s) s.textContent = m;
120:     console.error(m);
121:     Module.__fatal = m;
122: });
123: 
124: int main(int argc, char **argv)
125: {
126:     (void)argc; (void)argv;
127:     // Fail visibly if the preloaded WAD is missing or not an IWAD.
128:     FILE *wf = fopen("/doom1.wad", "rb");
129:     char magic[4] = {0};
130:     if (!wf || fread(magic, 1, 4, wf) != 4 || memcmp(magic, "IWAD", 4) != 0) {
131:         js_fatal("Cannot start: /doom1.wad is missing or not a valid IWAD. Serve doom.data next to doom.js.");
132:         if (wf) fclose(wf);
133:         return 1;
134:     }
135:     fclose(wf);
136:     char *args[] = { "doom", "-iwad", "/doom1.wad", "-nogui", NULL };
137:     doomgeneric_Create(4, args);
138:     for (;;) {
139:         doomgeneric_Tick();
140:         tick_count++;
141:         emscripten_sleep(0);   // let the browser handle events/paint
142:     }
143:     return 0;
144: }"}
